import{_ as o,o as t,c as l,a2 as i}from"./chunks/framework.DpXDHk3d.js";const d=JSON.parse('{"title":"13.4 倒闸操作与监护制度","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-4-dao-zha-cao-zuo-yu-jian-hu-zhi-du.md","filePath":"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-4-dao-zha-cao-zuo-yu-jian-hu-zhi-du.md","lastUpdated":1793096070000}'),n={name:"electrician/low-voltage-electrician/13-chapter-13-an-quan-zuo-ye-cao-zuo-gui-fan/13-4-dao-zha-cao-zuo-yu-jian-hu-zhi-du.md"};function e(r,a,s,u,h,c){return t(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="_13-4-倒闸操作与监护制度" tabindex="-1">13.4 倒闸操作与监护制度 <a class="header-anchor" href="#_13-4-倒闸操作与监护制度" aria-label="Permalink to &quot;13.4 倒闸操作与监护制度&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>&quot;倒闸&quot;就是拉合开关(闸),改变电气设备的运行状态。倒闸操作要求&quot;两人操作、一人监护、唱票复诵&quot;。这一节掌握操作票制度和倒闸的安全要求——这是安全管理的高频考点。</p><h2 id="一、什么是倒闸操作" tabindex="-1">一、什么是倒闸操作 <a class="header-anchor" href="#一、什么是倒闸操作" aria-label="Permalink to &quot;一、什么是倒闸操作&quot;">​</a></h2><p><strong>倒闸操作</strong>:拉开或合上开关(断路器、隔离开关),把设备从一种状态切换到另一种状态(送电、停电、检修)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>送电:先合隔离开关 ──► 后合断路器</span></span>
<span class="line"><span>停电:先拉断路器 ──► 后拉隔离开关</span></span></code></pre></div><h2 id="二、倒闸操作的基本原则-必背" tabindex="-1">二、倒闸操作的基本原则(必背) <a class="header-anchor" href="#二、倒闸操作的基本原则-必背" aria-label="Permalink to &quot;二、倒闸操作的基本原则(必背)&quot;">​</a></h2><ul><li><strong>送电</strong>时,先合<strong>隔离开关</strong>,后合<strong>断路器</strong>;</li><li><strong>停电</strong>时,先拉<strong>断路器</strong>,后拉<strong>隔离开关</strong>;</li></ul><blockquote><p>💡 为什么?<strong>断路器能切断短路电流,隔离开关不能</strong>。所以停电要先拉断路器(在可能带电情况下切断),隔离开关只能在无负荷(已断开电流)时拉;送电反之,先合隔离开关把&quot;电源接上&quot;但不带电流,最后合断路器才正式带电。</p></blockquote><blockquote><p>⚠️ 判断题高频:<strong>严禁带负荷拉合隔离开关</strong>;隔离开关不能切断负荷电流,只能在断路器断开之后拉。</p></blockquote><h2 id="三、操作票制度" tabindex="-1">三、操作票制度 <a class="header-anchor" href="#三、操作票制度" aria-label="Permalink to &quot;三、操作票制度&quot;">​</a></h2><ul><li>倒闸操作按<strong>操作票</strong>进行:事先写好操作项目和顺序,按票逐项执行;</li><li><strong>操作票是书面指令</strong>,防止忘项、漏项、错项;</li><li>操作完毕<strong>逐项打勾</strong>,最后汇报;</li><li>发令人、受令人、操作人、监护人职责分明。</li></ul><h2 id="四、操作监护制度-两人操作" tabindex="-1">四、操作监护制度(两人操作) <a class="header-anchor" href="#四、操作监护制度-两人操作" aria-label="Permalink to &quot;四、操作监护制度(两人操作)&quot;">​</a></h2><ul><li>倒闸操作一般由<strong>两人进行</strong>:<strong>一人操作、一人监护</strong>;</li><li>监护人负责<strong>发令、监督</strong>每一步是否正确,随时纠正错误;</li><li>操作时采用<strong>唱票复诵制</strong>:监护人唱票(念操作项目),操作人复诵(重复念),确认无误后<strong>操作</strong>;再核对状态;</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>监护人唱票(念操作内容) ──► 操作人复诵(大声重复) ──► 确认无误 ──► 操作</span></span></code></pre></div><blockquote><p>💡 通俗理解:<strong>&quot;唱票复诵&quot;就像两人核对口令,防止一个人走神做错</strong>——这是防止误操作的关键制度。</p></blockquote><h2 id="五、操作中的安全要求" tabindex="-1">五、操作中的安全要求 <a class="header-anchor" href="#五、操作中的安全要求" aria-label="Permalink to &quot;五、操作中的安全要求&quot;">​</a></h2><ul><li>操作前核对设备<strong>名称、编号</strong>,防找错设备;</li><li>操作时穿<strong>绝缘鞋、戴绝缘手套</strong>,使用相应绝缘工具;</li><li><strong>雨天、雾天</strong>尽量避免户外倒闸操作;</li><li>操作后检查设备状态、记录时间;</li><li>检修人员在场时,送电前确认<strong>人员已撤离、工作票已终结</strong>。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 送电:先合隔离开关、后合断路器;停电相反(先拉断路器、后拉隔离开关)。</li><li>✅ <strong>隔离开关不能带负荷拉合</strong>。</li><li>✅ 倒闸操作按<strong>操作票</strong>进行,两人操作、一人监护。</li><li>✅ <strong>唱票复诵</strong>防误操作。</li><li>⚠️ 易混点:断路器(能带负荷开断)与隔离开关(只能无负荷开断)的先后顺序——先断器后刀闸停电,先刀闸后断器送电。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>倒闸操作有严格顺序:停电先拉断路器、送电先合隔离开关。</li><li>操作票 + 两人监护 + 唱票复诵,层层防错。</li><li>隔离开关严禁带负荷拉合。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)停电时,应先拉断路器,后拉隔离开关。( )</li><li>(判断)隔离开关可以带负荷拉合。( )</li><li>(单选)倒闸操作时,实行&quot;唱票复诵&quot;制的目的是()。 A. 加快速度　B. 防止误操作　C. 减少人数　D. 省去操作票</li><li>(单选)倒闸操作一般应()进行。 A. 一人　B. 两人(一人操作、一人监护)　C. 三人　D. 无需人</li><li>(判断)倒闸操作应按操作票规定的项目和顺序逐项进行。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。停电先拉断路器,后拉隔离开关。</li><li><strong>×</strong>。隔离开关严禁带负荷拉合。</li><li><strong>B</strong>。唱票复诵防止误操作。</li><li><strong>B</strong>。两人操作、一人监护。</li><li><strong>√</strong>。按操作票逐项执行。</li></ol></details>`,25)])])}const p=o(n,[["render",e]]);export{d as __pageData,p as default};
